struct MyQueue{a:Vec<i32>,b:Vec<i32>}impl MyQueue{fn new()->Self{Self{a:vec![],b:vec![]}}fn push(&mut self,x:i32){self.a.push(x)}fn mv(&mut self){if self.b.is_empty(){while let Some(x)=self.a.pop(){self.b.push(x)}}}fn pop(&mut self)->i32{self.mv();self.b.pop().unwrap()}fn peek(&mut self)->i32{self.mv();*self.b.last().unwrap()}fn empty(&self)->bool{self.a.is_empty()&&self.b.is_empty()}}
